What is a Compiler:
// Simple compiler pipeline visualization
// Source code → Lexer → Tokens → Parser → AST → Semantic → IR → Optimizer → IR → CodeGen → Assembly

// A minimal compiler in JavaScript
class MiniCompiler {
  constructor() {
    this.tokens = [];
    this.ast = null;
  }

  // Phase 1: Lexical Analysis
  lex(source) {
    const tokens = [];
    let i = 0;
    while (i < source.length) {
      if (/\s/.test(source[i])) { i++; continue; }
      if (/[0-9]/.test(source[i])) {
        let num = '';
        while (i < source.length && /[0-9.]/.test(source[i])) num += source[i++];
        tokens.push({ type: 'NUMBER', value: parseFloat(num) });
      } else if ('+-*/()'.includes(source[i])) {
        tokens.push({ type: 'OPERATOR', value: source[i++] });
      } else {
        throw new Error(`Unexpected character: ${source[i]}`);
      }
    }
    tokens.push({ type: 'EOF', value: null });
    return tokens;
  }

  // Phase 2: Syntax Analysis (Recursive Descent Parser)
  parse(tokens) {
    let pos = 0;
    const peek = () => tokens[pos];
    const consume = (type) => {
      if (peek().type === type) return tokens[pos++];
      throw new Error(`Expected ${type}, got ${peek().type}`);
    };

    // Grammar: Expr → Term (('+'|'-') Term)*
    const parseExpr = () => {
      let left = parseTerm();
      while (peek().value === '+' || peek().value === '-') {
        const op = consume('OPERATOR').value;
        const right = parseTerm();
        left = { type: 'BINARY', operator: op, left, right };
      }
      return left;
    };

    // Grammar: Term → Factor (('*'|'/') Factor)*
    const parseTerm = () => {
      let left = parseFactor();
      while (peek().value === '*' || peek().value === '/') {
        const op = consume('OPERATOR').value;
        const right = parseFactor();
        left = { type: 'BINARY', operator: op, left, right };
      }
      return left;
    };

    // Grammar: Factor → NUMBER | '(' Expr ')'
    const parseFactor = () => {
      if (peek().type === 'NUMBER') {
        return { type: 'NUMBER', value: consume('NUMBER').value };
      }
      if (peek().value === '(') {
        consume('OPERATOR'); // '('
        const expr = parseExpr();
        consume('OPERATOR'); // ')'
        return expr;
      }
      throw new Error(`Unexpected token: ${peek().value}`);
    };

    const ast = parseExpr();
    consume('EOF');
    this.ast = ast;
    return ast;
  }

  // Phase 3: Code Generation (to simple assembly-like instructions)
  generate(ast) {
    const instructions = [];
    let tempCounter = 0;

    const emit = (inst) => instructions.push(inst);

    const gen = (node) => {
      if (node.type === 'NUMBER') {
        const temp = `t${tempCounter++}`;
        emit(`  ${temp} = ${node.value}`);
        return temp;
      }
      if (node.type === 'BINARY') {
        const left = gen(node.left);
        const right = gen(node.right);
        const result = `t${tempCounter++}`;
        emit(`  ${result} = ${left} ${node.operator} ${right}`);
        return result;
      }
    };

    const result = gen(ast);
    emit(`  return ${result}`);
    return instructions;
  }

  // Full pipeline
  compile(source) {
    console.log('Source:', source);
    const tokens = this.lex(source);
    console.log('Tokens:', tokens);
    const ast = this.parse(tokens);
    console.log('AST:', JSON.stringify(ast, null, 2));
    const code = this.generate(ast);
    console.log('Generated IR:');
    code.forEach(l => console.log(l));
    return { tokens, ast, code };
  }
}

