Interpreters vs Compilers:
// Performance comparison: Compiler vs Interpreter
const { performance } = require('perf_hooks');

// Interpreted approach: execute AST directly
function interpret(ast) {
  if (ast.type === 'NUMBER') return ast.value;
  if (ast.type === 'BINARY') {
    const left = interpret(ast.left);
    const right = interpret(ast.right);
    switch (ast.operator) {
      case '+': return left + right;
      case '-': return left - right;
      case '*': return left * right;
      case '/': return left / right;
    }
  }
}

// Compiled approach: generate code and execute
function compileAndRun(ast) {
  const instructions = [];
  let tempCounter = 0;

  function gen(node) {
    if (node.type === 'NUMBER') {
      const t = `t${tempCounter++}`;
      instructions.push({ op: 'LOAD', dest: t, val: node.value });
      return t;
    }
    if (node.type === 'BINARY') {
      const left = gen(node.left);
      const right = gen(node.right);
      const result = `t${tempCounter++}`;
      instructions.push({ op: node.operator, dest: result, left, right });
      return result;
    }
  }

  gen(ast);

  // Execute instructions (simplified VM)
  const registers = {};
  for (const inst of instructions) {
    switch (inst.op) {
      case 'LOAD': registers[inst.dest] = inst.val; break;
      case '+': registers[inst.dest] = registers[inst.left] + registers[inst.right]; break;
      case '-': registers[inst.dest] = registers[inst.left] - registers[inst.right]; break;
      case '*': registers[inst.dest] = registers[inst.left] * registers[inst.right]; break;
      case '/': registers[inst.dest] = registers[inst.left] / registers[inst.right]; break;
    }
  }
  return Object.values(registers).pop();
}

