Tokenization Basics:
// Complete lexer for a simple language
class Lexer {
  constructor(source) {
    this.source = source;
    this.pos = 0;
    this.line = 1;
    this.col = 1;
    this.tokens = [];

    // Token type definitions
    this.keywords = new Set(['if', 'else', 'while', 'for', 'return', 'let', 'const', 'function', 'class', 'true', 'false', 'null']);
  }

  tokenize() {
    while (this.pos < this.source.length) {
      const ch = this.source[this.pos];

      // Skip whitespace
      if (/\s/.test(ch)) {
        if (ch === '\n') { this.line++; this.col = 1; }
        else { this.col++; }
        this.pos++;
        continue;
      }

      // Comments (// and /* */)
      if (ch === '/' && this.peek() === '/') {
        while (this.pos < this.source.length && this.source[this.pos] !== '\n') this.pos++;
        continue;
      }
      if (ch === '/' && this.peek() === '*') {
        this.pos += 2;
        while (this.pos < this.source.length) {
          if (this.source[this.pos] === '*' && this.peek() === '/') { this.pos += 2; break; }
          if (this.source[this.pos] === '\n') this.line++;
          this.pos++;
        }
        continue;
      }

      // Numbers (integers and floats)
      if (/[0-9]/.test(ch)) {
        let num = '';
        while (this.pos < this.source.length && /[0-9]/.test(this.source[this.pos])) {
          num += this.source[this.pos++];
        }
        // Check for float
        if (this.source[this.pos] === '.' && /[0-9]/.test(this.peek(1))) {
          num += '.' + this.source[++this.pos];
          while (this.pos < this.source.length && /[0-9]/.test(this.source[++this.pos])) {
            num += this.source[this.pos];
          }
        }
        this.addToken('NUMBER', parseFloat(num));
        continue;
      }

      // Strings
      if (ch === '"' || ch === "'") {
        const quote = ch;
        let str = '';
        this.pos++;
        while (this.pos < this.source.length) {
          if (this.source[this.pos] === '\\') {
            str += this.source[this.pos + 1];
            this.pos += 2;
          } else if (this.source[this.pos] === quote) {
            this.pos++;
            break;
          } else {
            if (this.source[this.pos] === '\n') this.line++;
            str += this.source[this.pos++];
          }
        }
        this.addToken('STRING', str);
        continue;
      }

      // Identifiers and keywords
      if (/[a-zA-Z_$]/.test(ch)) {
        let ident = '';
        while (this.pos < this.source.length && /[a-zA-Z0-9_$]/.test(this.source[this.pos])) {
          ident += this.source[this.pos++];
        }
        const type = this.keywords.has(ident) ? 'KEYWORD' : 'IDENTIFIER';
        this.addToken(type, ident);
        continue;
      }

      // Multi-character operators
      if (ch === '=' && this.peek() === '=') { this.addToken('OPERATOR', '=='); this.pos += 2; continue; }
      if (ch === '!' && this.peek() === '=') { this.addToken('OPERATOR', '!='); this.pos += 2; continue; }
      if (ch === '<' && this.peek() === '=') { this.addToken('OPERATOR', '<='); this.pos += 2; continue; }
      if (ch === '>' && this.peek() === '=') { this.addToken('OPERATOR', '>='); this.pos += 2; continue; }
      if (ch === '&' && this.peek() === '&') { this.addToken('OPERATOR', '&&'); this.pos += 2; continue; }
      if (ch === '|' && this.peek() === '|') { this.addToken('OPERATOR', '||'); this.pos += 2; continue; }

      // Single-character operators and delimiters
      if ('+-*/%=<>!&|(){}[];,.:@#'.includes(ch)) {
        this.addToken('PUNCTUATION', ch);
        this.pos++;
        continue;
      }

      throw new Error(`Unexpected character '${ch}' at line ${this.line}, col ${this.col}`);
    }

    this.addToken('EOF', null);
    return this.tokens;
  }

  peek(offset = 1) {
    return this.source[this.pos + offset];
  }

  addToken(type, value) {
    this.tokens.push({ type, value, line: this.line, col: this.col });
    this.col += String(value).length;
  }
}

